// ========== PRIZEFIGHTER SPORT RULE ==========
const PF_ALLOWED_SPORTS = ['Gloved Boxing','Bare Knuckle Boxing (BKB)'];
function pfIsAllowedSport(s){ return PF_ALLOWED_SPORTS.includes((s||'').trim()); }
function pfSportOptionsHtml(selected){ return '<option value="">Select sport...</option>'+PF_ALLOWED_SPORTS.map(function(s){return '<option '+(s===selected?'selected':'')+'>'+s+'</option>';}).join(''); }


// ========== SESSION ==========
function isLoggedIn(){ return !!localStorage.getItem('pf_passport'); }
function getLoggedInName(){ return localStorage.getItem('pf_name')||'User'; }
function getLoggedInType(){ return localStorage.getItem('pf_type')||null; }
function getLoggedInInitials(){ return getLoggedInName().split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase(); }
function saveSession(token,name,type,passport){
  localStorage.setItem('pf_token',token||'');
  localStorage.setItem('pf_name',name||'');
  localStorage.setItem('pf_type',type||'');
  localStorage.setItem('pf_passport',passport||'');
}

// ========== API ==========
async function apiPost(ep,data,token){
  const h={'Content-Type':'application/json'};
  if(token) h['Authorization']='Bearer '+token;
  try{
    const r=await fetch(API_URL+ep,{method:'POST',headers:h,body:JSON.stringify(data)});
    return r.json();
  }catch(e){return {error:'Connection error'};}
}

