// ========== NAV ==========
function toggleMenu(){
  const menu=document.getElementById('dropdown-menu');
  const trigger=document.getElementById('menu-trigger');
  const overlay=document.getElementById('menu-overlay');
  const isOpen=menu.classList.contains('open');
  if(isOpen){menu.classList.remove('open');trigger.classList.remove('open');overlay.classList.remove('open');}
  else{menu.classList.add('open');trigger.classList.add('open');overlay.classList.add('open');}
}
function goHome(){
  closeMenu();
  setNav(null);
  showPage('home');
}
function closeMenu(){
  document.getElementById('dropdown-menu').classList.remove('open');
  document.getElementById('menu-trigger').classList.remove('open');
  document.getElementById('menu-overlay').classList.remove('open');
}
function openSheet(n){
  const el=document.getElementById('sheet-'+n);
  if(el){
    el.classList.add('open');
    document.body.style.overflow='hidden';
    if(n==='subscribe') setTimeout(initPayPalButton, 300);
  }
}
function closeSheet(n){
  const el=document.getElementById('sheet-'+n);
  if(el){el.classList.remove('open');document.body.style.overflow='';}
}
function closeBg(e,n){if(e.target===document.getElementById('sheet-'+n))closeSheet(n);}
function showToast(msg){
  const t=document.getElementById('toast');
  if(!t)return;
  t.innerHTML=msg;t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'),2800);
}
function showPage(name){
  if(name==='store'||name==='my-store'||name==='profile-store'){ name='merch'; }
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  const el=document.getElementById('page-'+name);
  if(el){el.classList.add('active');window.scrollTo(0,0);}
  document.body.classList.toggle('on-home',name==='home');
  if(name==='search'){setTimeout(()=>liveSearch(''),50);setTimeout(()=>initAds('search-ad-track'),60);}
  if(name==='inbox')renderInbox();
  if(name==='store'){renderStore([...storeProducts]);setTimeout(()=>initAds('store-ad-track'),60);}
  if(name==='my-store')renderMyStore();
  if(name==='plugins')renderPlugins();
  if(name==='fan-profile')renderFanProfile();
  if(name==='merch'){renderMerch();}
  if(name==='tshirts'){renderTshirts();}
  if(name==='admin')renderAdmin();
  if(name==='profile-store'){}
  if(name==='profile-store'){}
  if(name==='fighter-profile')renderFighterAccount();
}
function setNav(btn){
  document.querySelectorAll('.bnav-btn').forEach(b=>b.classList.remove('active'));
  if(btn)btn.classList.add('active');
}
function goSearch(val){
  showPage('search');setNav(document.querySelectorAll('.bnav-btn')[1]);
  const inp=document.getElementById('search-input');if(inp)inp.value=val||'';
  liveSearch(val||'');
}
function shareProfile(name){
  if(navigator.share)navigator.share({title:name+' on Prizefighter',text:'Check out '+name+' on Prizefighter.info',url:'https://prizefighter.info'}).catch(()=>{});
  else navigator.clipboard.writeText('https://prizefighter.info').then(()=>showToast('Profile link copied! 🔗'));
}

// ========== FIGHTER CARDS ==========
function renderCard(f,onclick){
  return '<div class="fighter-card" onclick="'+onclick+'">'
    +'<div class="fighter-avatar">'+f.initials+'</div>'
    +'<div class="fighter-info">'
    +'<div class="fighter-name">'+f.name+' <span style="color:var(--gray-text);font-weight:400;font-size:12px">'+f.ringname+'</span></div>'
    +'<div class="fighter-meta">'+f.sport+' &middot; '+f.city+', '+f.country+' &middot; '+f.weight+'</div>'
    +'<div class="fighter-record"><span class="w">'+f.wins+'W</span> <span class="l">'+f.losses+'L</span> <span class="d">'+f.draws+'D</span> &middot; '+f.kos+' KOs</div>'
    +'</div>'
    +(f.verified?'<div class="verified-badge">&#10003; Verified</div>':'')
    +'</div>';
}

