function toggleLike(btn){
  if(!isLoggedIn()){showToast('Sign in to like &#128077;');openSheet('fan-signup');return;}
  const cnt=btn.querySelector('.like-cnt');if(!cnt)return;
  const cur=parseInt(cnt.textContent)||0;
  const liked=btn.dataset.liked==='1';
  btn.dataset.liked=liked?'0':'1';
  cnt.textContent=liked?cur-1:cur+1;
}

function toggleCommentsEl(el){if(el)el.style.display=el.style.display==='none'?'block':'none';}

function getCommentFormHTML(listId,inputId){
  if(isLoggedIn()){
    return '<div class="comment-input-row">'
      +'<input class="comment-input" type="text" placeholder="Add a comment..." id="'+inputId+'">'
      +'<button class="comment-submit" onclick="postComment(\''+listId+'\',\''+inputId+'\')">Post</button>'
      +'</div>';
  }
  return '<div style="padding:8px;background:var(--gray-mid);border-radius:2px;font-size:11px;color:var(--gray-text);text-align:center;margin-top:6px">'
    +'<a href="#" onclick="openSheet(\'fan-signup\');return false" style="color:var(--red);font-weight:800;text-decoration:none">Sign up as a fan</a>'
    +' or <a href="#" onclick="openSheet(\'signup\');return false" style="color:var(--red);font-weight:800;text-decoration:none">fighter</a> to comment'
    +'</div>';
}

function postComment(listId,inputId){
  if(!isLoggedIn()){showToast('Sign in to comment');return;}
  const input=document.getElementById(inputId);
  if(!input||!input.value.trim())return;
  const text=input.value.trim();
  const name=getLoggedInName();
  const initials=getLoggedInInitials();
  const type=getLoggedInType();
  const list=document.getElementById(listId);if(!list)return;
  const div=document.createElement('div');
  div.className='comment';div.style.margin='8px 0';
  div.innerHTML='<div class="comment-avatar" style="'+(type==='fighter'?'background:var(--red);color:#fff':'')+'">'
    +initials+'</div><div class="comment-body">'
    +'<div class="comment-name">'+name+'</div>'
    +'<div class="comment-text">'+text+'</div>'
    +'<div class="comment-time">Just now</div>'
    +'</div>';
  list.appendChild(div);
  input.value='';
}

function previewPostImg(fid,input){
  const file=input.files[0];if(!file)return;
  // Check if user can post images
  if (false) {
    showToast('Image posting is a Plugins advantage &#11088;');
    openSheet('subscribe');
    input.value = '';
    return;
  }
  const quota = getImageQuota();
  if (quota.remaining <= 0) {
    showToast('Image limit reached. ' + MAX_MERCH_PRODUCTS + ' images per 28 days. Resets ' + getQuotaResetDate());
    input.value = '';
    return;
  }
  if(file.size>5*1024*1024){showToast('Image must be under 5MB');return;}
  const reader=new FileReader();
  reader.onload=e=>{
    const preview=document.getElementById('post-img-preview-'+fid);
    if(preview){
      preview.innerHTML='<div style="position:relative;display:inline-block;width:100%">'
        +'<img src="'+e.target.result+'" style="width:100%;max-height:200px;object-fit:contain;border-radius:2px;border:1px solid var(--gray-border)">'
        +'<div style="position:absolute;top:4px;right:4px;background:rgba(0,0,0,0.7);color:#fff;padding:2px 8px;border-radius:2px;font-size:10px">'
        +quota.remaining+' img remaining</div>'
        +'</div>';
    }
  };
  reader.readAsDataURL(file);
}

function clearPostImg(fid){
  const p=document.getElementById('post-img-preview-'+fid);
  const i=document.getElementById('post-img-'+fid);
  if(p)p.innerHTML='';if(i)i.value='';
}

function addPost(fid){
  const input=document.getElementById('new-post-'+fid);
  const imgPreview=document.getElementById('post-img-preview-'+fid);
  const imgEl=imgPreview?imgPreview.querySelector('img'):null;
  const text=input?input.value.trim():'';
  if(!text&&!imgEl){showToast('Add text or photo to post');return;}
  const feed=document.getElementById('post-feed-'+fid);
  const name=isLoggedIn()?getLoggedInName():(fighters.find(x=>x.id===fid)||{name:'Fighter'}).name;
  const initials=name.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase();
  const pid='p'+fid+Date.now();
  const div=document.createElement('div');
  div.className='post-card';div.style.marginBottom='10px';
  let inner='<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">'
    +'<div class="fighter-avatar" style="width:36px;height:36px;font-size:12px">'+initials+'</div>'
    +'<div><div style="font-size:13px;font-weight:800">'+name+'</div>'
    +'<div style="font-size:10px;color:var(--gray-text)">Just now</div></div>'
    +'<button onclick="this.parentNode.parentNode.remove();showToast(\'Post deleted\')" style="margin-left:auto;background:none;border:none;color:var(--gray-text);cursor:pointer;font-size:16px">&#128465;</button>'
    +'</div>';
  if(text)inner+='<div style="font-size:13px;color:var(--gray-light);line-height:1.6;margin-bottom:8px">'+text+'</div>';
  if(imgEl)inner+='<img src="'+imgEl.src+'" style="width:100%;max-height:220px;object-fit:contain;border-radius:2px;margin-bottom:8px;border:1px solid var(--gray-border)">';
  inner+='<div class="post-actions">'
    +'<button class="post-action-btn" data-liked="0" onclick="toggleLike(this)">&#10004; <span class="like-cnt">0</span></button>'
    +'<button class="post-action-btn" onclick="toggleCommentsEl(this.parentNode.nextSibling)">&#128172; Comment</button>'
    +'<button class="post-action-btn" onclick="shareProfile(\'Post on Prizefighter\')">&#128279; Share</button>'
    +'</div>'
    +'<div class="comments-box" style="display:none">'
    +'<div id="'+pid+'-cl"></div>'
    +getCommentFormHTML(pid+'-cl',pid+'-ci')
    +'</div>';
  div.innerHTML=inner;
  feed.prepend(div);
  if(input)input.value='';
  clearPostImg(fid);
  if(imgEl) useImageQuota();
  showToast('Post shared! &#128690;');
}

// ========== INBOX ==========
function renderInbox(){
  const el=document.getElementById('inbox-list');if(!el)return;
  // Update badge count
  const unread = messages.filter(m => m.unread).length;
  const badge = document.querySelector('.bnav-notif');
  if (badge) {
    badge.style.display = unread > 0 ? 'block' : 'none';
    badge.title = unread + ' unread';
  }
  el.innerHTML=messages.map(m=>'<div class="inbox-item" onclick="openThread('+m.id+')">'
    +'<div class="inbox-avatar">'+m.initials+'</div>'
    +'<div class="inbox-info"><div class="inbox-name">'+m.from+'</div><div class="inbox-preview">'+m.preview+'</div></div>'
    +'<div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0">'
    +'<div class="inbox-time">'+m.time+'</div>'
    +(m.unread?'<div class="inbox-unread"></div>':'')
    +'</div></div>'
  ).join('');
}

function openThread(id){
  const m=messages.find(x=>x.id===id);if(!m)return;
  currentMsgId=id;m.unread=false;
  document.getElementById('msg-thread-name').textContent=m.from;
  document.getElementById('msg-thread').innerHTML=m.thread.map(t=>
    '<div><div class="msg-bubble '+(t.sent?'sent':'recv')+'">'+t.text+'</div><div class="msg-time">'+t.time+'</div></div>'
  ).join('');
  showPage('message');
}

function openMsgTo(fid,fname){
  if(!isLoggedIn()){showToast('Sign in to send messages');openSheet('login');return;}
  let m=messages.find(x=>x.from===fname);
  if(!m){
    m={id:Date.now(),from:fname,initials:fname.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase(),preview:'Start a conversation...',time:'Now',unread:false,thread:[]};
    messages.unshift(m);
  }
  currentMsgId=m.id;
  openThread(m.id);
}

function sendMessage(){
  const input=document.getElementById('msg-input');
  const text=input?input.value.trim():'';
  if(!text||!currentMsgId)return;
  const m=messages.find(x=>x.id===currentMsgId);if(!m)return;
  m.thread.push({sent:true,text,time:'Now'});
  const div=document.createElement('div');
  div.innerHTML='<div class="msg-bubble sent">'+text+'</div><div class="msg-time">Now</div>';
  const thread=document.getElementById('msg-thread');
  if(thread){thread.appendChild(div);thread.scrollTop=99999;}
  input.value='';
}

// ========== SEARCH ==========
let searchTimer=null;
function liveSearch(val){
  clearTimeout(searchTimer);
  searchTimer=setTimeout(()=>fallbackSearch(val),300);
}

function fallbackSearch(val){
  const v=(val||'').toLowerCase();
  let list=[...fighters];
  if(currentFilter==='Gloved Boxing')list=list.filter(f=>f.sport==='Gloved Boxing');
  else if(currentFilter==='Bare Knuckle' || currentFilter==='Bare Knuckle Boxing')list=list.filter(f=>f.sport.includes('Bare Knuckle')); 
  if(v)list=list.filter(f=>
    f.name.toLowerCase().includes(v)||
    f.ringname.toLowerCase().includes(v)||
    f.country.toLowerCase().includes(v)||
    f.weight.toLowerCase().includes(v)||
    (f.city||'').toLowerCase().includes(v)||
    (f.gym||'').toLowerCase().includes(v)||
    (f.sport||'').toLowerCase().includes(v)||
    (f.stance||'').toLowerCase().includes(v)||
    (f.status||'').toLowerCase().includes(v)
  );
  list.sort((a,b)=>b.verified-a.verified);
  const el=document.getElementById('search-list');if(!el)return;
  const label=document.getElementById('results-label');
  if(!list.length){
    el.innerHTML='<div style="text-align:center;padding:30px 20px">'
      +'<div style="font-size:40px;margin-bottom:12px">&#129354;</div>'
      +'<div style="font-size:15px;font-weight:800;color:var(--white);margin-bottom:6px">No fighters found</div>'
      +'<div style="font-size:12px;color:var(--gray-text);margin-bottom:16px">Be the first fighter from your area on Prizefighter</div>'
      +'<button class="btn-primary" style="max-width:220px;padding:12px" onclick="openSheet(\'signup\')">Create Fighter Profile</button>'
      +'</div>';
    return;
  }
  el.innerHTML=list.map(f=>renderCard(f,'openProfile('+f.id+')')).join('');
  if(label)label.innerHTML=list.length+' <span>Fighter'+(list.length!==1?'s':'')+'</span>';
}

function setFilter(btn,cat){
  currentFilter=cat;
  document.querySelectorAll('.filter-bar .chip').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  liveSearch(document.getElementById('search-input')?.value||'');
}

// ========== MERCH ==========
function renderStore(products){
  const grid=document.getElementById('store-grid');
  const label=document.getElementById('store-label');
  if(!grid)return;
  if(!products||!products.length){grid.innerHTML='<div style="grid-column:1/-1;padding:30px;text-align:center;color:var(--gray-text)">No products found.</div>';return;}
  if(label)label.innerHTML=products.length+' <span>Product'+(products.length!==1?'s':'')+'</span>';
  grid.innerHTML=products.map(p=>'<div class="product-card" onclick="openProduct('+p.id+')">'
    +'<div class="product-img">'+(p.image?'<img src="'+p.image+'" alt="'+p.name+'">':p.emoji)+'</div>'
    +'<div class="product-info">'
    +'<div class="product-name">'+p.name+'</div>'
    +'<div class="product-price">$'+parseFloat(p.price).toFixed(2)+'</div>'
    +'<div class="product-seller">By <b>'+p.seller+'</b></div>'
    +'<span class="cond-tag '+(p.condition==='New'?'cond-new':p.condition==='Used'?'cond-used':'cond-exc')+'">'+p.condition+'</span>'
    +'</div></div>'
  ).join('');
}

function searchProducts(val){
  const v=(val||'').toLowerCase();
  let list=[...storeProducts];
  if(storeFilter!=='All')list=list.filter(p=>p.category===storeFilter);
  if(v)list=list.filter(p=>p.name.toLowerCase().includes(v)||p.desc.toLowerCase().includes(v)||p.seller.toLowerCase().includes(v));
  renderStore(list);
}

function filterProducts(btn,cat){
  storeFilter=cat;
  document.querySelectorAll('.store-filter-bar .chip').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  searchProducts(document.getElementById('store-search')?.value||'');
}

function openProduct(id,fromPage){
  const p=storeProducts.find(x=>x.id===id);if(!p)return;
  const backPage=fromPage||'store';
  const sellerInitials=p.seller.split(' ').map(w=>w[0]).join('').slice(0,2).toUpperCase();
  document.getElementById('product-detail-content').innerHTML=
    '<div class="profile-topbar">'
    +'<button class="back-btn" onclick="showPage(\'' +backPage+ '\')">&#8592;</button>'
    +'<span class="profile-topbar-title" style="color:#fff;font-weight:900;letter-spacing:1px">PRIZEFIGHTER <span style="color:var(--gray-text)">MERCH</span>'
    +'<div class="profile-topbar-actions"><button class="icon-btn" onclick="shareProductItem('+p.id+')">&#128279;</button></div>'
    +'</div>'
    +'<div style="width:100%;aspect-ratio:1;background:var(--gray-mid);display:flex;align-items:center;justify-content:center;font-size:80px;max-height:500px;overflow:hidden">'
    +(p.image?'<img src="'+p.image+'" style="width:100%;height:100%;object-fit:contain">':p.emoji)
    +'</div>'
    +'<div style="padding:16px;border-bottom:1px solid var(--gray-border)">'
    +'<div style="font-family:var(--font-display);font-size:28px;font-weight:900;color:var(--red)">$'+parseFloat(p.price).toFixed(2)+'</div>'
    +'<div style="font-size:18px;font-weight:800;margin:6px 0">'+p.name+'</div>'
    +'<span class="cond-tag '+(p.condition==='New'?'cond-new':p.condition==='Used'?'cond-used':'cond-exc')+'" style="margin-bottom:10px;display:inline-block">'+p.condition+'</span>'
    +'<p style="font-size:13px;color:var(--gray-light);line-height:1.7">'+p.desc+'</p>'
    +'</div>'
    +'<div style="padding:16px;border-bottom:1px solid var(--gray-border)">'
    +'<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--gray-text);margin-bottom:10px">Sold By</div>'
    +'<div style="display:flex;align-items:center;gap:12px;cursor:pointer" onclick="openProfile('+p.sellerId+')">'
    +'<div class="fighter-avatar" style="width:44px;height:44px;font-size:14px">'+sellerInitials+'</div>'
    +'<div><div style="font-size:14px;font-weight:800">'+p.seller+'</div>'
    +'<div style="font-size:10px;color:var(--blue)">'+p.sellerPassport+' &middot; View Profile &#8594;</div></div>'
    +'</div></div>'
    +'<div style="padding:16px;display:flex;flex-direction:column;gap:10px">'
    +'<button class="btn-primary" onclick="buyWhatsapp('+p.id+')">&#128172; Buy Now &#8212; WhatsApp Seller</button>'
    +'<button class="btn-secondary" onclick="buyEmail('+p.id+')">&#128231; Contact via Email</button>'
    +'<button class="btn-secondary" onclick="shareProductItem('+p.id+')">&#128279; Share This Product</button>'
    +'</div>'
    +'<p style="padding:0 16px 16px;font-size:10px;color:var(--gray-text);text-align:center;line-height:1.6">Prizefighter connects buyers and sellers. All transactions are between buyer and seller directly.</p>';
  showPage('product');
}

function buyWhatsapp(id){
  const p=storeProducts.find(x=>x.id===id);if(!p)return;
  const msg=encodeURIComponent('Hi '+p.seller+', I saw your listing on Prizefighter for "'+p.name+'" at $'+p.price+'. Is it still available?');
  const phone=p.sellerWhatsapp.replace(/[^0-9]/g,'');
  window.open('https://wa.me/'+phone+'?text='+msg,'_blank');
}

function buyEmail(id){
  const p=storeProducts.find(x=>x.id===id);if(!p)return;
  const sub=encodeURIComponent('Prizefighter Store: '+p.name);
  const body=encodeURIComponent('Hi '+p.seller+',\n\nI saw your listing on Prizefighter for "'+p.name+'" at $'+p.price+'.\n\nIs it still available?');
  window.location.href='mailto:'+p.sellerEmail+'?subject='+sub+'&body='+body;
}

function shareProductItem(id){
  const p=storeProducts.find(x=>x.id===id);if(!p)return;
  if(navigator.share)navigator.share({title:p.name+' on Prizefighter Merch',text:p.name+' for $'+p.price+' on Prizefighter!',url:'https://prizefighter.info'}).catch(()=>{});
  else navigator.clipboard.writeText('https://prizefighter.info').then(()=>showToast('Product link copied! &#128279;'));
}

function viewProfileStore(fighterId,fighterName){
  const myProducts=storeProducts.filter(p=>p.sellerId===fighterId);
  const content=document.getElementById('profile-store-content');if(!content)return;
  content.innerHTML='<div style="padding:16px;border-bottom:1px solid var(--gray-border);background:var(--black2)">'
    +'<div style="font-size:14px;font-weight:800">'+fighterName+"'s Store</div>"
    +'<div style="font-size:11px;color:var(--gray-text)">'+myProducts.length+' product'+(myProducts.length!==1?'s':'')+' listed</div>'
    +'</div>'
    +'<div class="store-grid">'
    +(myProducts.length?myProducts.map(p=>'<div class="product-card" onclick="openProduct('+p.id+',\'profile-store\')">'
      +(p.image ? '<div class="product-img" style="padding:0;overflow:hidden"><img src="'+p.image+'" style="width:100%;height:100%;object-fit:contain"></div>' : '<div class="product-img">'+p.emoji+'</div>')
      +'<div class="product-info"><div class="product-name">'+p.name+'</div>'
      +'<div class="product-price">$'+parseFloat(p.price).toFixed(2)+'</div>'
      +'<span class="cond-tag '+(p.condition==='New'?'cond-new':'cond-used')+'">'+p.condition+'</span>'
      +'</div></div>'
    ).join(''):'<div style="grid-column:1/-1;padding:30px;text-align:center;color:var(--gray-text)">No products listed yet.</div>')
    +'</div>';
  showPage('profile-store');
}

