// PayFast removed - PayPal only

function payWithPayPal(){
  showToast('Please use the PayPal button below &#128179;');
}

function initPayPalButton() {
  const containerId = 'paypal-button-container-P-7US37021JL981242RNI7M2VA';
  const container = document.getElementById(containerId);
  if (!container) return;
  if (container.querySelector('iframe, button, a')) return;

  if (typeof window.paypal === 'undefined' || typeof window.paypal.Buttons !== 'function') {
    container.innerHTML = '<a href="https://www.paypal.com/paypalme/prizefighterinfo" target="_blank" rel="noopener" style="display:inline-block;width:100%;padding:12px 14px;background:var(--red);color:#fff;text-align:center;border-radius:2px;text-decoration:none;font-weight:800">Pay with PayPal</a>';
    return;
  }

  window.paypal.Buttons({
    style: {
      shape: 'rect',
      color: 'gold',
      layout: 'vertical',
      label: 'subscribe'
    },
    createSubscription: function(data, actions) {
      return actions.subscription.create({
        plan_id: 'P-7US37021JL981242RNI7M2VA'
      });
    },
    onApprove: function(data, actions) {
      activateLevelUp(1);
      closeSheet('subscribe');
      showToast('Plugin activated! Welcome &#11088;');
      checkSession();
    },
    onError: function(err) {
      showToast('PayPal error. Please try again.');
    },
    onCancel: function() {
      showToast('Payment cancelled.');
    }
  }).render('#' + containerId);
}

// ========== AUTH ==========
let loginType='fighter';
function setLoginType(type){
  loginType=type;
  document.getElementById('login-fighter-btn')?.classList.toggle('active',type==='fighter');
  document.getElementById('login-fan-btn')?.classList.toggle('active',type==='fan');
}

function validateRequired(ids){
  let ok=true;
  ids.forEach(id=>{
    const el=document.getElementById(id);if(!el)return;
    const val=el.type==='checkbox'?el.checked:el.value.trim();
    if(!val){el.classList.add('error');ok=false;}
    else el.classList.remove('error');
  });
  return ok;
}

async function submitLogin(){
  const email=document.getElementById('login-email')?.value.trim();
  const password=document.getElementById('login-password')?.value;
  if(!email||!password){showToast('Please enter email and password');return;}
  showToast('Signing in... &#9203;');
  try{
    const ep=loginType==='fighter'?'/fighters/login':'/fans/login';
    const result=await apiPost(ep,{email,password},null);
    if(result.error){showToast('Error: '+result.error);return;}
    const name=loginType==='fighter'?result.fighter?.fighter_name:result.fan?.full_name;
    const passport=loginType==='fighter'?result.fighter?.passport_id:result.fan?.passport_id;
    saveSession(result.token,name,loginType,passport);
    showToast('Welcome back '+name+'! &#128690;');
    closeSheet('login');checkSession();
  }catch(e){showToast('Connection error');}
}

async function submitFighterProfile(){
  const req=['f-name','f-ringname','f-dob','f-walkout','f-country','f-city','f-email','f-whatsapp','f-password','f-sport','f-weight','f-stance','f-status','f-gym','f-bio','f-facebook'];
  const chk=['chk-fb-fighter','chk-yt-fighter','chk-app-fighter','chk-terms-fighter','chk-real-fighter','chk-notify-fighter','chk-active-fighter'];
  if(!validateRequired([...req,...chk])){
    showToast('Please complete all required fields &#9888;');
    document.querySelector('.error')?.scrollIntoView({behavior:'smooth',block:'center'});
    return;
  }
  showToast('Creating your profile... &#9203;');
  try{
    const result=await apiPost('/fighters/signup',{
      email:document.getElementById('f-email').value.trim(),
      password:document.getElementById('f-password').value,
      whatsapp:document.getElementById('f-whatsapp').value.trim(),
      fighter_name:document.getElementById('f-name').value.trim(),
      ring_name:document.getElementById('f-ringname').value.trim(),
      date_of_birth:document.getElementById('f-dob').value,
      walkout_song:document.getElementById('f-walkout').value.trim(),
      country:document.getElementById('f-country').value.trim(),
      city:document.getElementById('f-city').value.trim(),
      sport:document.getElementById('f-sport').value,
      weight_class:document.getElementById('f-weight').value,
      stance:document.getElementById('f-stance').value,
      status:document.getElementById('f-status').value,
      gym:document.getElementById('f-gym').value.trim(),
      height_cm:parseFloat(document.getElementById('f-height').value)||0,
      reach_cm:parseFloat(document.getElementById('f-reach').value)||0,
      wins:parseInt(document.getElementById('f-wins').value)||0,
      losses:parseInt(document.getElementById('f-losses').value)||0,
      draws:parseInt(document.getElementById('f-draws').value)||0,
      kos:parseInt(document.getElementById('f-kos').value)||0,
      no_contests:parseInt(document.getElementById('f-nc').value)||0,
      am_wins:parseInt(document.getElementById('f-am-wins').value)||0,
      am_losses:parseInt(document.getElementById('f-am-losses').value)||0,
      am_draws:parseInt(document.getElementById('f-am-draws').value)||0,
      wc_fights:parseInt(document.getElementById('f-wc').value)||0,
      bio:document.getElementById('f-bio').value.trim(),
      facebook_url:document.getElementById('f-facebook').value.trim(),
      youtube_url:document.getElementById('f-youtube')?.value.trim()||''
    });
    if(result.token){
      saveSession(result.token,result.fighter?.fighter_name,'fighter',result.passport_id);
      showToast('Profile created! Welcome '+result.passport_id+' &#128690;');
      checkSession();
    }else if(result.error){showToast('Error: '+result.error);return;}
    else{showToast('Profile submitted! Welcome to Prizefighter &#128690;');}
    closeSheet('signup');
  }catch(e){showToast('Profile submitted! Welcome to Prizefighter &#128690;');closeSheet('signup');}
}

async function submitFanSignup(){
  const req=['fan-name','fan-username','fan-dob','fan-country','fan-email','fan-whatsapp','fan-password'];
  const chk=['chk-fb-fan','chk-yt-fan','chk-app-fan','chk-terms-fan','chk-notify-fan','chk-active-fan'];
  if(!validateRequired([...req,...chk])){
    showToast('Please complete all required fields &#9888;');
    document.querySelector('.error')?.scrollIntoView({behavior:'smooth',block:'center'});
    return;
  }
  showToast('Creating fan account... &#9203;');
  try{
    const result=await apiPost('/fans/signup',{
      email:document.getElementById('fan-email').value.trim(),
      password:document.getElementById('fan-password').value,
      whatsapp:document.getElementById('fan-whatsapp').value.trim(),
      full_name:document.getElementById('fan-name').value.trim(),
      username:document.getElementById('fan-username').value.trim(),
      date_of_birth:document.getElementById('fan-dob').value,
      country:document.getElementById('fan-country').value.trim()
    });
    if(result.token){
      saveSession(result.token,result.fan?.full_name,'fan',result.passport_id);
      showToast('Fan profile created! Welcome &#128090;');
      checkSession();
    }else{showToast('Fan sign up submitted! Welcome &#128090;');}
    closeSheet('fan-signup');
  }catch(e){closeSheet('fan-signup');showToast('Fan sign up submitted! Welcome &#128090;');}
}

function checkSession(){
  checkAccountStatus();
  const passport=localStorage.getItem('pf_passport');
  const name=localStorage.getItem('pf_name');
  const type=localStorage.getItem('pf_type');
  const inner=document.getElementById('dropdown-inner');if(!inner)return;
  inner.querySelectorAll('.session-item').forEach(el=>el.remove());
  if(passport&&name){
    const item=document.createElement('div');
    item.className='session-item';
    item.style.cssText='padding:12px 20px;border-bottom:1px solid #2e2e2e;background:#111';
    item.innerHTML='<div style="font-size:9px;letter-spacing:2px;text-transform:uppercase;color:#777;margin-bottom:2px">Signed in as</div>'
      +'<div style="font-size:13px;font-weight:800;color:#f0f0f0">'+name+'</div>'
      +'<div style="font-size:10px;color:#e8192c;margin-top:2px">'+passport+' &middot; '+(type||'').toUpperCase()+'</div>';
    inner.insertBefore(item,inner.firstChild);
    const logoutBtn=document.createElement('button');
    logoutBtn.className='dropdown-item session-item';
    logoutBtn.innerHTML='<span class="dropdown-icon">&#128682;</span><div><div class="dropdown-label">Sign Out</div><div class="dropdown-sub">Log out of Prizefighter</div></div>';
    logoutBtn.onclick=()=>{localStorage.clear();showToast('Signed out. See you soon! &#128075;');closeMenu();setTimeout(()=>location.reload(),800);};
    inner.appendChild(logoutBtn);
    inner.querySelectorAll('.dropdown-item').forEach(btn=>{
      if(btn.textContent&&btn.textContent.includes('Sign In'))btn.style.display='none';
    });
  }
}

