function goProfile() {
  const type = getLoggedInType();
  const passport = localStorage.getItem('pf_passport');
  if (!passport) {
    openSheet('login');
    return;
  }
  if (type === 'fan') {
    showPage('fan-profile');
  } else if (type === 'fighter') {
    showPage('fighter-profile');
  } else {
    openSheet('login');
  }
}

