function cancelLevelUp() {
  if (!confirm("Cancel Plugin? All Plugin features, store listings, posts and ads will be deleted immediately. No refunds. Are you sure?")) return;
  disableLevelUp();
  // In production: call API to remove store products, ads, posts created during Plugins
  showToast("Plugins cancelled. Profile reverted to free account.");
  renderFanProfile();
}

function deleteAccount() {
  if (!confirm("DELETE your account permanently? This cannot be undone. All your data will be removed.")) return;
  if (!confirm("Are you absolutely sure? Press OK to permanently delete your Prizefighter account.")) return;
  localStorage.clear();
  showToast("Account deletion requested. You will receive a confirmation email.");
  showPage("home");
  // In production: call API /fans/delete or /fighters/delete
}


// ========== ACCOUNT STATUS SYSTEM ==========
// FREE PROFILE: shadow ban after 30 days, delete after 60 days
// LEVEL UP: debit order 5 days before renewal, cancel = immediate disable + delete plugins content
// FAN: same as free fighter - shadow ban 30 days, delete 60 days
// FAN LEVEL UP: same as fighter plugins

function checkAccountStatus() {
  const passport = localStorage.getItem('pf_passport');
  if (!passport) return;

  const lastLogin = localStorage.getItem('pf_last_login');
  const accountType = localStorage.getItem('pf_type');
  const isLevelUpUser = localStorage.getItem('pf_plugin') === 'true';
  const subExpiry = localStorage.getItem('pf_sub_expiry');

  const now = new Date();
  const last = lastLogin ? new Date(lastLogin) : now;
  const daysSince = Math.floor((now - last) / (1000 * 60 * 60 * 24));

  // Update last login
  localStorage.setItem('pf_last_login', now.toISOString());

  // Check Plugin subscription expiry
  if (isLevelUpUser && subExpiry) {
    const expiry = new Date(subExpiry);
    const daysToExpiry = Math.floor((expiry - now) / (1000 * 60 * 60 * 24));

    if (daysToExpiry <= 5 && daysToExpiry > 0) {
      showToast('⚠️ Plugin renews in ' + daysToExpiry + ' days. Check your debit order.');
    } else if (daysToExpiry <= 0) {
      // Subscription expired - disable plugins
      disableLevelUp();
    }
  }

  // Free profile / fan dormant checks (frontend warning only - backend handles actual deletion)
  if (!isLevelUpUser) {
    if (daysSince >= 55) {
      showToast('⚠️ Your profile will be deleted in ' + (60 - daysSince) + ' days. Log in to keep it active.');
    } else if (daysSince >= 28) {
      showToast('⚠️ Your profile is inactive. Log in regularly to avoid shadow ban.');
    }
  }
}

function disableLevelUp() {
  localStorage.removeItem('pf_plugin');
  localStorage.removeItem('pf_sub_expiry');
  showToast('Plugin subscription ended. Profile reverted to free.');
}

function activateLevelUp(months) {
  const expiry = new Date();
  expiry.setMonth(expiry.getMonth() + (months || 1));
  localStorage.setItem('pf_plugin', 'true');
  localStorage.setItem('pf_sub_expiry', expiry.toISOString());
  showToast('Plugin activated! Expires ' + expiry.toLocaleDateString());
}

function isLevelUp() {
  if (localStorage.getItem('pf_plugin') !== 'true') return false;
  const expiry = localStorage.getItem('pf_sub_expiry');
  if (!expiry) return false;
  return new Date(expiry) > new Date();
}

function getLevelUpDaysLeft() {
  const expiry = localStorage.getItem('pf_sub_expiry');
  if (!expiry) return 0;
  return Math.max(0, Math.floor((new Date(expiry) - new Date()) / (1000 * 60 * 60 * 24)));
}


