async function updateStatCount() {
  const el = document.getElementById('stat-count');
  // Try Supabase direct count first
  try {
    if (db) {
      const { count, error } = await db
        .from('fighters')
        .select('*', { count: 'exact', head: true });
      if (!error && count !== null) {
        if (el) el.textContent = count;
        return;
      }
    }
  } catch(e) {}
  // Fallback to API
  try {
    const result = await apiGet('/fighters');
    if (result.fighters) {
      if (el) el.textContent = result.fighters.length;
      return;
    }
  } catch(e) {}
  // Final fallback - demo count
  if (el) el.textContent = fighters.length;
}


