async function adminVerify(passportId) {
  if (!confirm('Verify fighter ' + passportId + '?')) return;
  try {
    if (db) {
      const { error } = await db.from('fighters').update({is_verified: true}).eq('passport_id', passportId);
      if (!error) { showToast('Fighter verified! &#10003;'); adminLoadFighters(); return; }
    }
    const r = await apiPost('/admin/verify', {passport_id: passportId}, localStorage.getItem('pf_token'));
    if (r.success) { showToast('Fighter verified! &#10003;'); adminLoadFighters(); }
    else showToast('Error: ' + (r.error || 'Could not verify'));
  } catch(e) { showToast('Verify failed. Check connection.'); }
}

