function contactFighterWA(whatsapp, name) {
  const phone = (whatsapp || '').replace(/[^0-9]/g, '');
  if (!phone || phone.length < 8) {
    showToast('WhatsApp not available for this fighter');
    return;
  }
  const msg = encodeURIComponent('Hi ' + name + ', I found your profile on Prizefighter.info and would like to get in touch regarding a fight opportunity.');
  window.open('https://wa.me/' + phone + '?text=' + msg, '_blank');
}


// ========== IMAGE QUOTA SYSTEM ==========
// Free: no images in posts
// Plugins: 5 images per 28 days, resets every 28 days
// Deleted image returns to balance

function getImageQuota() {
  if (!isLevelUp()) return { allowed: false, used: 0, max: 0, remaining: 0 };
  const key = 'pf_img_quota';
  const resetKey = 'pf_img_reset';
  const now = new Date();
  const resetDate = localStorage.getItem(resetKey);
  
  // Check if 28 days have passed - reset
  if (!resetDate || (now - new Date(resetDate)) > 28 * 24 * 60 * 60 * 1000) {
    localStorage.setItem(key, '0');
    localStorage.setItem(resetKey, now.toISOString());
  }
  
  const used = parseInt(localStorage.getItem(key) || '0');
  const max = 5;
  return { allowed: true, used, max, remaining: Math.max(0, max - used) };
}

function useImageQuota() {
  if (!isLevelUp()) return false;
  const quota = getImageQuota();
  if (quota.remaining <= 0) {
    showToast('Image limit reached. 5 images per 28 days on Plugins. &#11088;');
    return false;
  }
  const used = quota.used + 1;
  localStorage.setItem('pf_img_quota', used.toString());
  showToast('Image posted. ' + (quota.remaining - 1) + ' of 5 remaining this period &#128247;');
  return true;
}

function returnImageQuota() {
  if (!isLevelUp()) return;
  const used = parseInt(localStorage.getItem('pf_img_quota') || '0');
  if (used > 0) {
    localStorage.setItem('pf_img_quota', (used - 1).toString());
    showToast('Image removed. Balance restored &#10003;');
  }
}

function getQuotaResetDate() {
  const resetDate = localStorage.getItem('pf_img_reset');
  if (!resetDate) return 'Not started';
  const reset = new Date(new Date(resetDate).getTime() + 28 * 24 * 60 * 60 * 1000);
  return reset.toLocaleDateString('en-GB', {day:'2-digit', month:'short', year:'numeric'});
}

// ========== PRODUCT LIMIT SYSTEM ==========
// Plugins: max 5 products in store
const MAX_MERCH_PRODUCTS = 5;

function canAddProduct() {
  if (!isLevelUp()) {
    showToast('Plugins required to list products &#11088;');
    openSheet('subscribe');
    return false;
  }
  const myName = getLoggedInName();
  const myProducts = storeProducts.filter(p => p.seller === myName && !p.sold);
  if (myProducts.length >= MAX_MERCH_PRODUCTS) {
    showToast('Product limit reached. Max ' + MAX_MERCH_PRODUCTS + ' products on Plugins. Store Album Plugin coming soon.');
    return false;
  }
  return true;
}


