function selectTshirtSize(btn, size) {
  document.querySelectorAll('.size-btn').forEach(b => { b.style.borderColor = 'var(--gray-border)'; b.style.color = 'var(--white)'; });
  btn.style.borderColor = 'var(--red)';
  btn.style.color = 'var(--red)';
  window._currentTshirtSize = size;
}

function orderTshirt(id) {
  const p = tshirtProducts.find(x => x.id === id); if (!p) return;
  const size = window._currentTshirtSize || '[please add your size]';
  const msg = encodeURIComponent('Hi Prizefighter, I want to order: ' + p.name + ' ($' + p.price + ' excl. delivery). Size: ' + size + '. Please confirm availability and payment details.');
  window.open('https://wa.me/27060919545600?text=' + msg, '_blank');
}

function isLoggedInAs(fighterId) {
  // Check if the logged-in fighter is the owner of this profile
  const passport = localStorage.getItem('pf_passport');
  const type = getLoggedInType();
  if (!passport || type !== 'fighter') return false;
  // Match by sellerId stored in session
  const sessionId = parseInt(localStorage.getItem('pf_fighter_id') || '0');
  return sessionId === fighterId;
}


