function populateMerchScrollBar(containerId) {
  const bar = document.getElementById(containerId);
  if (!bar) return;
  // Use official PF merch products
  const items = typeof merchProducts !== 'undefined' ? merchProducts.slice(0, 12) : [];
  if (!items.length) {
    // Show placeholder merch items
    const placeholders = [
      { emoji: '👕', name: 'PF Boxing Tee', price: 29 },
      { emoji: '🧢', name: 'PF Cap', price: 24 },
      { emoji: '🥊', name: 'PF Gloves', price: 89 },
      { emoji: '🩳', name: 'PF Fight Shorts', price: 45 },
      { emoji: '🎒', name: 'PF Gym Bag', price: 59 },
      { emoji: '🧤', name: 'PF Hand Wraps', price: 19 },
    ];
    bar.innerHTML = placeholders.map(function(item) {
      return '<div onclick="showPage(\'merch\')" style="flex-shrink:0;width:120px;cursor:pointer;background:var(--gray-dark);border:1px solid var(--gray-border);border-radius:2px;overflow:hidden">'
        + '<div style="width:120px;height:120px;display:flex;align-items:center;justify-content:center;font-size:44px;background:var(--black2)">' + item.emoji + '</div>'
        + '<div style="padding:7px">'
        + '<div style="font-size:11px;font-weight:800;color:var(--white);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + item.name + '</div>'
        + '<div style="font-size:12px;color:var(--red);font-weight:700;margin-top:2px">$' + item.price + '</div>'
        + '</div></div>';
    }).join('');
    return;
  }
  bar.innerHTML = items.map(function(p) {
    return '<div onclick="openMerchProduct(\'' + p.id + '\')" style="flex-shrink:0;width:120px;cursor:pointer;background:var(--gray-dark);border:1px solid var(--gray-border);border-radius:2px;overflow:hidden">'
      + (p.image ? '<div style="width:120px;height:120px;overflow:hidden"><img src="' + p.image + '" style="width:100%;height:100%;object-fit:contain"></div>'
                 : '<div style="width:120px;height:120px;display:flex;align-items:center;justify-content:center;font-size:44px;background:var(--black2)">' + p.emoji + '</div>')
      + '<div style="padding:7px">'
      + '<div style="font-size:11px;font-weight:800;color:var(--white);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + p.name + '</div>'
      + '<div style="font-size:12px;color:var(--red);font-weight:700;margin-top:2px">$' + p.price + '</div>'
      + '</div></div>';
  }).join('');
}

