// ========== PHASE 2 FRONTEND PLATFORM UPGRADE ==========
// Static demo foundation for fighter/fan profiles, advertising, plugins and merch.
// Backend automation still requires Cloudflare Worker/Railway + database + PayPal webhooks.

function getActiveAds(){
  const demoAds = [
    {label:'YOUR BRAND HERE', sub:'$500 / 28 days · 3 month contract', url:'#'},
    {label:'GEAR & EQUIPMENT', sub:'Reach fighters on every profile', url:'#'},
    {label:'NUTRITION & SUPPLEMENTS', sub:'Combat audience advertising slot', url:'#'},
    {label:'PROMOTERS & MANAGERS', sub:'Find your next fighter here', url:'#'},
    {label:'FIGHT APPAREL', sub:'Premium Prizefighter ad slot', url:'#'}
  ];
  try { return JSON.parse(localStorage.getItem('pf_ads') || 'null') || demoAds; } catch(e){ return demoAds; }
}

function buildProfileAds(){
  const ads = getActiveAds();
  return [...ads, ...ads].map(function(a){
    const cleanUrl = (a.url || '#').replace(/'/g,'');
    const action = cleanUrl && cleanUrl !== '#' ? "window.open('" + cleanUrl + "','_blank')" : "openSheet('sponsor')";
    return '<div class="profile-ad-item" onclick="'+action+'" style="cursor:pointer">'
      +'<div style="width:220px;height:64px;border-radius:2px;background:#1a1a1a;border:1px solid #2e2e2e;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:8px;text-align:center;gap:3px">'
      +'<div style="font-size:9px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;color:#f0f0f0">'+a.label+'</div>'
      +'<div style="font-size:8px;color:#777">'+a.sub+'</div>'
      +'<div style="font-size:8px;color:var(--red);font-weight:800;text-transform:uppercase">Enquire →</div>'
      +'</div></div>';
  }).join('');
}

