function toggleLike(btn, fid){
  if(!isLoggedIn()){showToast('Sign in to like 👍');openSheet('fan-signup');return;}
  const cnt=btn.querySelector('.like-cnt');
  const liked=btn.dataset.liked==='1';
  btn.dataset.liked=liked?'0':'1';
  if(cnt){ const cur=parseInt(cnt.textContent)||0; cnt.textContent=liked?Math.max(0,cur-1):cur+1; }
  if(fid && typeof fid === 'number'){
    let ids=[]; try{ ids=JSON.parse(localStorage.getItem('pf_liked_ids')||'[]'); }catch(e){}
    ids = liked ? ids.filter(function(id){return id!==fid;}) : Array.from(new Set(ids.concat([fid])));
    localStorage.setItem('pf_liked_ids', JSON.stringify(ids));
  }
}

// ========== PHASE 3: LOCAL PLATFORM CONTROL LAYER ==========
function pfRead(key, fallback){ try { return JSON.parse(localStorage.getItem(key) || 'null') || fallback; } catch(e){ return fallback; } }
function pfWrite(key, value){ localStorage.setItem(key, JSON.stringify(value)); }
function pfEscape(v){ return String(v || '').replace(/[&<>'"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]; }); }
function pfSheetValues(sheetId){
  const sheet=document.getElementById('sheet-'+sheetId); if(!sheet) return {};
  const fields=[...sheet.querySelectorAll('input,select,textarea')];
  const out={};
  fields.forEach(function(el,idx){
    const key=(el.id || el.name || el.previousElementSibling?.textContent || ('field_'+idx)).replace(/\s+/g,'_').toLowerCase();
    out[key]=el.type==='checkbox'?el.checked:el.value;
  });
  return out;
}
function submitAdEnquiry(){
  const v=pfSheetValues('sponsor');
  const company=v.company_name || v.field_0 || '';
  const email=v.contact_email || v.field_1 || '';
  const logo=v.logo_/_icon_url || v.field_2 || '';
  const url=v.landing_page_url || v.field_3 || '';
  const adType=v.ad_type || v.field_4 || 'Scrolling Profile Banner - $500 / 28 days';
  const contract=!!(v.chk_ad_contract || v.field_5);
  if(!company || !email || !url){ showToast('Complete company, email and landing URL ⚠️'); return; }
  const queue=pfRead('pf_ad_queue',[]);
  queue.unshift({id:Date.now(),company,email,logo,url,adType,contract,status:'pending',created:new Date().toISOString(),period:'28 days',contractTerm:'3 months'});
  pfWrite('pf_ad_queue',queue);
  showToast('Ad enquiry saved for admin approval 💼');
  closeSheet('sponsor');
}
function submitReport(){
  const v=pfSheetValues('report');
  const reason=v.reason || v.field_0 || 'Other';
  const details=v.details || v.field_1 || '';
  const reports=pfRead('pf_reports',[]);
  reports.unshift({id:Date.now(),reason,details,profile:'Current profile',status:'new',created:new Date().toISOString()});
  pfWrite('pf_reports',reports);
  showToast('Report saved for admin review 🛡️');
  closeSheet('report');
}
function approveAd(id){
  const q=pfRead('pf_ad_queue',[]); const item=q.find(x=>x.id===id); if(!item) return;
  item.status='active'; item.approved=new Date().toISOString();
  const ads=pfRead('pf_ads',[]);
  ads.unshift({label:item.company.toUpperCase(),sub:item.adType.replace('Scrolling Profile Banner - ',''),url:item.url,logo:item.logo,expires:new Date(Date.now()+28*86400000).toISOString()});
  pfWrite('pf_ad_queue',q); pfWrite('pf_ads',ads);
  showToast('Ad activated for demo banners ✅'); adminLoadAds();
}
function rejectAd(id){ const q=pfRead('pf_ad_queue',[]).filter(x=>x.id!==id); pfWrite('pf_ad_queue',q); showToast('Ad enquiry removed'); adminLoadAds(); }
function clearReport(id){ const r=pfRead('pf_reports',[]).filter(x=>x.id!==id); pfWrite('pf_reports',r); showToast('Report cleared'); adminLoadReports(); }

