// ========== PHASE 4: SOCIAL INTERACTION + VERIFICATION GATES ==========
const PF_PHASE4_VERSION='phase4-social-verification';
function pfIsVerifiedUser(){ return isLoggedIn() && !!localStorage.getItem('pf_passport'); }
function pfRequireVerified(action){
  if(!isLoggedIn()){ showToast('Sign in or register to '+action+' 🔐'); openSheet('login'); return false; }
  if(!pfIsVerifiedUser()){ showToast('Verified Prizefighter account required to '+action+' ✅'); return false; }
  return true;
}
function pfPostsKey(fid){ return 'pf_posts_'+fid; }
function pfDefaultPosts(fid){
  const f=fighters.find(x=>x.id===fid)||fighters[0];
  return [{id:'welcome-'+fid,author:f.name,initials:f.initials,time:'Just joined Prizefighter',text:'Welcome to my Prizefighter profile! '+f.ringname+' is ready.',image:'',likes:0,comments:[{name:'Fight Club SA',initials:'FC',text:'Solid profile. Ready for the fight world. 🔥',time:'1 day ago'}]}];
}
function pfGetPosts(fid){ const saved=pfRead(pfPostsKey(fid),null); return saved&&saved.length?saved:pfDefaultPosts(fid); }
function pfSavePosts(fid,posts){ pfWrite(pfPostsKey(fid),posts); }
function pfPostHTML(fid,p){
  const comments=(p.comments||[]).map(function(c){return '<div class="comment" style="margin:8px 0"><div class="comment-avatar">'+pfEscape(c.initials||'PF')+'</div><div class="comment-body"><div class="comment-name">'+pfEscape(c.name)+'</div><div class="comment-text">'+pfEscape(c.text)+'</div><div class="comment-time">'+pfEscape(c.time||'Just now')+'</div></div></div>';}).join('');
  return '<div class="post-card" data-post-id="'+pfEscape(p.id)+'" style="margin-bottom:10px">'
    +'<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px"><div class="fighter-avatar" style="width:36px;height:36px;font-size:12px">'+pfEscape(p.initials)+'</div><div><div style="font-size:13px;font-weight:800">'+pfEscape(p.author)+'</div><div style="font-size:10px;color:var(--gray-text)">'+pfEscape(p.time)+'</div></div></div>'
    +(p.text?'<div style="font-size:13px;color:var(--gray-light);line-height:1.6;margin-bottom:8px">'+pfEscape(p.text)+'</div>':'')
    +(p.image?'<img src="'+p.image+'" style="width:100%;max-height:220px;object-fit:contain;border-radius:2px;margin-bottom:8px;border:1px solid var(--gray-border)">':'')
    +'<div class="post-actions"><button class="post-action-btn" data-liked="0" onclick="phase4LikePost(this,'+fid+',\''+pfEscape(p.id)+'\')">✔ <span class="like-cnt">'+(p.likes||0)+'</span></button><button class="post-action-btn" onclick="toggleCommentsEl(document.getElementById(\'comments-'+pfEscape(p.id)+'\'))">💬 Comment</button><button class="post-action-btn" onclick="shareProfile(\'Prizefighter post\')">🔗 Share</button><button class="post-action-btn" onclick="phase4ReportPost(\''+pfEscape(p.id)+'\')">🚩 Report</button></div>'
    +'<div class="comments-box" id="comments-'+pfEscape(p.id)+'" style="display:none"><div id="comments-list-'+pfEscape(p.id)+'">'+comments+'</div><div class="comment-input-row"><input class="comment-input" type="text" placeholder="Add a comment..." id="comment-input-'+pfEscape(p.id)+'"><button class="comment-submit" onclick="phase4AddComment('+fid+',\''+pfEscape(p.id)+'\')">Post</button></div></div></div>';
}
function phase4RenderPosts(fid){ const feed=document.getElementById('post-feed-'+fid); if(feed) feed.innerHTML=pfGetPosts(fid).map(function(p){return pfPostHTML(fid,p);}).join(''); }
function phase4LikePost(btn,fid,pid){
  if(!pfRequireVerified('like posts')) return;
  const liked=btn.dataset.liked==='1'; btn.dataset.liked=liked?'0':'1';
  const posts=pfGetPosts(fid); const p=posts.find(x=>String(x.id)===String(pid)); if(p){ p.likes=Math.max(0,(p.likes||0)+(liked?-1:1)); pfSavePosts(fid,posts); }
  const cnt=btn.querySelector('.like-cnt'); if(cnt) cnt.textContent=p?p.likes:cnt.textContent;
}
function phase4AddComment(fid,pid){
  if(!pfRequireVerified('comment')) return;
  const input=document.getElementById('comment-input-'+pid); if(!input||!input.value.trim()) return;
  const posts=pfGetPosts(fid); const p=posts.find(x=>String(x.id)===String(pid)); if(!p) return;
  p.comments=p.comments||[]; p.comments.push({name:getLoggedInName(),initials:getLoggedInInitials(),text:input.value.trim(),time:'Just now'});
  pfSavePosts(fid,posts); input.value=''; phase4RenderPosts(fid); const box=document.getElementById('comments-'+pid); if(box) box.style.display='block'; showToast('Comment posted 💬');
}
function phase4ReportPost(pid){
  const reports=pfRead('pf_reports',[]); reports.unshift({id:Date.now(),reason:'Reported post',details:'Post ID: '+pid,profile:'Prizefighter post',status:'new',created:new Date().toISOString()}); pfWrite('pf_reports',reports); showToast('Post report saved for admin 🚩');
}
const _phase4AddPostOld = typeof addPost==='function' ? addPost : null;
addPost=function(fid){
  if(!pfRequireVerified('post updates')) return;
  const input=document.getElementById('new-post-'+fid); const imgPreview=document.getElementById('post-img-preview-'+fid); const imgEl=imgPreview?imgPreview.querySelector('img'):null;
  const text=input?input.value.trim():''; if(!text&&!imgEl){showToast('Add text or photo to post');return;}
  const posts=pfGetPosts(fid); posts.unshift({id:'p'+Date.now(),author:getLoggedInName(),initials:getLoggedInInitials(),time:'Just now',text:text,image:imgEl?imgEl.src:'',likes:0,comments:[]}); pfSavePosts(fid,posts);
  if(input) input.value=''; if(typeof clearPostImg==='function') clearPostImg(fid); phase4RenderPosts(fid); showToast('Post shared to profile ✅');
};
const _phase4OpenProfileOld = typeof openProfile==='function' ? openProfile : null;
openProfile=function(id){
  if(_phase4OpenProfileOld) _phase4OpenProfileOld(id);
  setTimeout(function(){ phase4RenderPosts(id); const box=document.getElementById('new-post-'+id); if(box){ box.placeholder = pfIsVerifiedUser() ? 'Share an update...' : 'Sign in with a verified fighter or fan account to post...'; } },30);
};
const _phase4PostCommentOld = typeof postComment==='function' ? postComment : null;
postComment=function(listId,inputId){ if(!pfRequireVerified('comment')) return; if(_phase4PostCommentOld) _phase4PostCommentOld(listId,inputId); };
const _phase4ToggleLikeOld = typeof toggleLike==='function' ? toggleLike : null;
toggleLike=function(btn,fid){ if(!pfRequireVerified('like')) return; if(_phase4ToggleLikeOld) _phase4ToggleLikeOld(btn,fid); };
function phase4QuickFanLogin(){ saveSession('demo-token','Prizefighter Fan','fan','PF-FAN-DEMO'); showToast('Demo fan account active ✅'); closeSheet('fan-signup'); showPage('fan-profile'); }
function phase4QuickFighterLogin(){ saveSession('demo-token','ZARDOZ CERFF','fighter','PF-000001'); showToast('Demo fighter account active ✅'); closeSheet('login'); openProfile(1); }
function adminLoadSocial(){ const el=document.getElementById('admin-list'); if(!el) return; const posts=pfGetPosts(1); el.innerHTML='<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--gray-text);margin-bottom:10px">Social Moderation</div>'+posts.map(function(p){return '<div style="background:var(--gray-dark);border:1px solid var(--gray-border);padding:12px;margin-bottom:8px"><div style="font-size:13px;font-weight:900">'+pfEscape(p.author)+'</div><div style="font-size:11px;color:var(--gray-light);line-height:1.5">'+pfEscape(p.text||'Photo post')+'</div><div style="font-size:10px;color:var(--gray-text);margin-top:6px">'+(p.comments||[]).length+' comments · '+(p.likes||0)+' likes</div></div>';}).join(''); }
const _phase4RenderAdminOld = typeof renderAdmin==='function' ? renderAdmin : null;
renderAdmin=function(){ if(_phase4RenderAdminOld) _phase4RenderAdminOld(); setTimeout(function(){ const grid=document.querySelector('#admin-content div[style*="grid-template-columns"]'); if(grid && !document.getElementById('phase4-social-admin-btn')) grid.insertAdjacentHTML('beforeend','<button id="phase4-social-admin-btn" class="btn-secondary" onclick="adminLoadSocial()">💬 Social</button>'); const title=document.querySelector('#admin-content div[style*="PHASE 3"]'); if(title) title.innerHTML='PHASE 4 <span style="color:var(--red)">SOCIAL CONTROL CENTRE</span>'; },20); };

// ========== PHASE 5: SIGNUP VALIDATION + LOCAL APPROVAL QUEUES ==========
function pf5get(id){ return (document.getElementById(id)?.value || '').trim(); }
function pf5checked(id){ return !!document.getElementById(id)?.checked; }
function pf5store(key, value){ localStorage.setItem(key, JSON.stringify(value)); }
function pf5load(key, fallback){ try{return JSON.parse(localStorage.getItem(key)||'');}catch(e){return fallback;} }
function pf5isFacebookProfile(url){
  try{ const u=new URL(url); const h=u.hostname.replace(/^www\./,'').toLowerCase();
    if(!['facebook.com','m.facebook.com','fb.com'].includes(h)) return false;
    const path=u.pathname.replace(/^\//,'').toLowerCase();
    if(!path || path.includes('pages/') || path.includes('groups/') || path.includes('share/') || path.includes('profile.php')) return false;
    return true;
  }catch(e){ return false; }
}
function pf5isBoxrec(url){
  if(!url) return true;
  try{ const u=new URL(url); return u.hostname.toLowerCase().includes('boxrec.com') && u.pathname.length>1; }catch(e){ return false; }
}
function pf5passport(prefix){ return prefix+'-'+String(Date.now()).slice(-6); }
function pf5initials(name){ return name.split(/\s+/).map(w=>w[0]||'').join('').slice(0,2).toUpperCase(); }
function pf5queue(type, item){ const key='pf5_'+type+'_queue'; const q=pf5load(key,[]); q.unshift(item); pf5store(key,q); return q; }

// Override signup for frontend demo: creates searchable submitted fighter + admin queue.
async function submitFighterProfile(){
  const req=['f-name','f-ringname','f-dob','f-walkout','f-country','f-city','f-email','f-whatsapp','f-password','f-sport','f-weight','f-stance','f-status','f-gym','f-bio','f-facebook'];
  const chk=['chk-fb-fighter','chk-yt-fighter','chk-app-fighter','chk-terms-fighter','chk-real-fighter','chk-notify-fighter','chk-active-fighter'];
  if(!validateRequired([...req,...chk])){ showToast('Complete all required fighter fields ⚠️'); document.querySelector('.error')?.scrollIntoView({behavior:'smooth',block:'center'}); return; }
  const facebook=pf5get('f-facebook'); const boxrec=pf5get('f-boxrec'); const selectedSport=pf5get('f-sport');
  if(!pfIsAllowedSport(selectedSport)){ showToast('Prizefighter only accepts Gloved Boxing or Bare Knuckle Boxing / BKB'); return; }
  if(!pf5isFacebookProfile(facebook)){ showToast('Use a Facebook profile link only — no page, group or share link'); return; }
  if(!pf5isBoxrec(boxrec)){ showToast('BoxRec link must be from boxrec.com'); return; }
  const name=pf5get('f-name').toUpperCase();
  const id=Date.now();
  const fighter={
    id, name, ringname:pf5get('f-ringname'), dob:pf5get('f-dob'), walkout:pf5get('f-walkout'), sport:selectedSport,
    country:pf5get('f-country'), city:pf5get('f-city'), wins:+pf5get('f-wins')||0, losses:+pf5get('f-losses')||0, draws:+pf5get('f-draws')||0, kos:+pf5get('f-kos')||0, nc:+pf5get('f-nc')||0,
    amWins:+pf5get('f-am-wins')||0, amLosses:+pf5get('f-am-losses')||0, amDraws:+pf5get('f-am-draws')||0, wcFights:+pf5get('f-wc')||0,
    weight:pf5get('f-weight'), stance:pf5get('f-stance'), gym:pf5get('f-gym'), height:pf5get('f-height')||'—', reach:pf5get('f-reach')||'—', status:pf5get('f-status'), bio:pf5get('f-bio'),
    verified:false, submitted:true, facebook, boxrec, sponsor:null, initials:pf5initials(name), passport:pf5passport('PF')
  };
  fighters.push(fighter);
  pf5queue('fighter',{...fighter, email:pf5get('f-email'), whatsapp:pf5get('f-whatsapp'), created:new Date().toISOString(), approval:'pending'});
  saveSession('demo-token', name, 'fighter', fighter.passport);
  closeSheet('signup'); checkSession(); showToast('Fighter submitted — now searchable and waiting for admin verification');
  goSearch(name);
}

// Override fan signup for frontend demo: creates fan approval queue and session.
async function submitFanSignup(){
  const req=['fan-name','fan-username','fan-dob','fan-country','fan-email','fan-whatsapp','fan-password'];
  const chk=['chk-fb-fan','chk-yt-fan','chk-app-fan','chk-terms-fan','chk-notify-fan','chk-active-fan'];
  if(!validateRequired([...req,...chk])){ showToast('Complete all required fan fields ⚠️'); document.querySelector('.error')?.scrollIntoView({behavior:'smooth',block:'center'}); return; }
  const fan={id:Date.now(), name:pf5get('fan-name'), username:pf5get('fan-username'), country:pf5get('fan-country'), email:pf5get('fan-email'), whatsapp:pf5get('fan-whatsapp'), passport:pf5passport('FAN'), verified:false, created:new Date().toISOString(), approval:'pending'};
  pf5queue('fan', fan);
  saveSession('demo-token', fan.name, 'fan', fan.passport);
  closeSheet('fan-signup'); checkSession(); showToast('Fan profile submitted — admin approval queue updated'); showPage('fan-profile');
}

// Stronger search: includes submitted demo fighters, passport, BoxRec and social fields.
function fallbackSearch(val){
  const v=(val||'').toLowerCase(); let list=[...fighters];
  if(currentFilter==='Gloved Boxing') list=list.filter(f=>f.sport==='Gloved Boxing');
  else if(currentFilter==='Bare Knuckle' || currentFilter==='Bare Knuckle Boxing') list=list.filter(f=>(f.sport||'').includes('Bare Knuckle'));
  if(v) list=list.filter(f=>[f.name,f.ringname,f.country,f.city,f.weight,f.gym,f.sport,f.stance,f.status,f.passport,f.boxrec,f.facebook].some(x=>(x||'').toString().toLowerCase().includes(v)));
  list.sort((a,b)=>(b.verified===true)-(a.verified===true) || (b.submitted===true)-(a.submitted===true));
  const el=document.getElementById('search-list'); if(!el) return; const label=document.getElementById('results-label');
  if(!list.length){ el.innerHTML='<div style="text-align:center;padding:30px 20px"><div style="font-size:40px;margin-bottom:12px">🥊</div><div style="font-size:15px;font-weight:800;color:var(--white);margin-bottom:6px">No fighters found</div><div style="font-size:12px;color:var(--gray-text);margin-bottom:16px">Be the first fighter from your area on Prizefighter</div><button class="btn-primary" style="max-width:220px;padding:12px" onclick="openSheet(\'signup\')">Create Fighter Profile</button></div>'; return; }
  el.innerHTML=list.map(f=>renderCard(f,'openProfile('+f.id+')')).join(''); if(label) label.innerHTML=list.length+' <span>Fighter'+(list.length!==1?'s':'')+'</span>';
}

// Admin queue override: shows real local demo queues and approval buttons.
function adminLoadPending(){
  const el=document.getElementById('admin-list'); if(!el) return;
  const fq=pf5load('pf5_fighter_queue',[]); const fanq=pf5load('pf5_fan_queue',[]);
  const rows=[];
  fq.forEach((f,i)=>rows.push('<div class="phase5-admin-card"><div class="phase5-admin-title">🥊 '+f.name+'</div><div class="phase5-admin-meta">Fighter · '+(f.city||'')+', '+(f.country||'')+' · '+(f.weight||'')+'<br>Email: '+(f.email||'')+' · WhatsApp: '+(f.whatsapp||'')+'<br>Facebook: '+(f.facebook||'')+'<br>BoxRec: '+(f.boxrec||'Not supplied')+'</div><span class="phase5-pill warn">Pending verification</span><span class="phase5-pill '+(pf5isFacebookProfile(f.facebook)?'ok':'bad')+'">Facebook check</span><span class="phase5-pill '+(pf5isBoxrec(f.boxrec)?'ok':'bad')+'">BoxRec check</span><div class="phase5-actions"><button class="btn-primary" style="padding:9px 12px;font-size:11px" onclick="pf5ApproveFighter('+f.id+')">Approve fighter</button><button class="btn-secondary" style="padding:9px 12px;font-size:11px" onclick="pf5Reject(\'fighter\','+i+')">Reject</button></div><div class="phase5-small">Approval turns on the verified badge in this browser demo. Backend phase will store this permanently.</div></div>'));
  fanq.forEach((f,i)=>rows.push('<div class="phase5-admin-card"><div class="phase5-admin-title">😎 '+f.name+'</div><div class="phase5-admin-meta">Fan · @'+(f.username||'')+' · '+(f.country||'')+'<br>Email: '+(f.email||'')+' · WhatsApp: '+(f.whatsapp||'')+'</div><span class="phase5-pill warn">Pending fan approval</span><div class="phase5-actions"><button class="btn-primary" style="padding:9px 12px;font-size:11px" onclick="pf5ApproveFan('+f.id+')">Approve fan</button><button class="btn-secondary" style="padding:9px 12px;font-size:11px" onclick="pf5Reject(\'fan\','+i+')">Reject</button></div></div>'));
  el.innerHTML = rows.length ? rows.join('') : '<div style="color:var(--green);font-size:13px;padding:20px;text-align:center">✓ No pending fighter or fan approvals</div>';
}
function pf5ApproveFighter(id){ const q=pf5load('pf5_fighter_queue',[]); const item=q.find(x=>x.id===id); const f=fighters.find(x=>x.id===id); if(f){f.verified=true;f.submitted=false;} pf5store('pf5_fighter_queue',q.filter(x=>x.id!==id)); showToast((item?.name||'Fighter')+' approved ✓'); adminLoadPending(); }
function pf5ApproveFan(id){ const q=pf5load('pf5_fan_queue',[]); const item=q.find(x=>x.id===id); pf5store('pf5_fan_queue',q.filter(x=>x.id!==id)); showToast((item?.name||'Fan')+' approved ✓'); adminLoadPending(); }
function pf5Reject(type,index){ const key='pf5_'+type+'_queue'; const q=pf5load(key,[]); q.splice(index,1); pf5store(key,q); showToast('Application rejected/removed'); adminLoadPending(); }

// Make BoxRec button open the fighter-specific approved link when present.
const pf5OpenProfileBase = openProfile;
openProfile = function(id){ pf5OpenProfileBase(id); const f=fighters.find(x=>x.id===id); setTimeout(()=>{ if(f?.boxrec){ const btn=[...document.querySelectorAll('button')].find(b=>b.textContent.includes('View on BoxRec')); if(btn) btn.onclick=()=>window.open(f.boxrec,'_blank'); } },30); };

// ========== PHASE 6: PLUGIN PURCHASES + CONTRACT STATUS DASHBOARD ==========
const PF_PHASE6_VERSION='phase6-commercial-demo';
function pf6load(key, fallback){ try{return JSON.parse(localStorage.getItem(key)||'');}catch(e){return fallback;} }
function pf6save(key, val){ localStorage.setItem(key, JSON.stringify(val)); }
function pf6moneyPluginId(name){ return String(name||'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''); }
function pf6daysLeft(date){ if(!date) return 0; return Math.max(0, Math.ceil((new Date(date).getTime()-Date.now())/86400000)); }
function pf6activePlugins(){ return pf6load('pf6_plugins',[]); }
function pf6activeSponsorPack(){ return pf6activePlugins().find(p=>p.id==='five-sponsor-bar' && p.status==='active' && pf6daysLeft(p.expires)>0); }
function pf6contractStatus(expires){ const d=pf6daysLeft(expires); if(d<=0) return '<span class="phase6-status expired">Expired</span>'; if(d<=7) return '<span class="phase6-status warn">Renew soon</span>'; return '<span class="phase6-status active">Active · '+d+' days</span>'; }
function pf6purchasePlugin(id,name,price){
  const plugins=pf6activePlugins().filter(p=>!(p.id===id && p.status==='active'));
  plugins.unshift({id,name,price,status:'active',created:new Date().toISOString(),expires:new Date(Date.now()+28*86400000).toISOString(),contractTerm:'3 months',payment:'Demo payment recorded'});
  pf6save('pf6_plugins',plugins);
  showToast(name+' activated for 28 days ✅');
  renderPlugins();
}
function pf6cancelPlugin(id){ const plugins=pf6activePlugins().map(p=>p.id===id?{...p,status:'cancelled'}:p); pf6save('pf6_plugins',plugins); showToast('Plugin marked cancelled'); renderPlugins(); }
function pf6expirePlugin(id){ const plugins=pf6activePlugins().map(p=>p.id===id?{...p,expires:new Date(Date.now()-86400000).toISOString()}:p); pf6save('pf6_plugins',plugins); showToast('Plugin expired for demo test'); if(document.getElementById('admin-list')) adminLoadMoney(); }

renderPlugins=function(){
  const el=document.getElementById('plugins-list'); if(!el)return;
  const active=pf6activePlugins();
  const catalogue=[
    {icon:'📘',id:'facebook-profile-link',name:'Facebook Profile Link',price:'Free',desc:'Adds a Facebook profile icon to the fighter plugin bar. Only personal Facebook profile links are accepted.',free:true},
    {icon:'⭐',id:'single-sponsor-bar',name:'Single Sponsor Bar',price:'Free',desc:'One non-clickable sponsor logo/name on the fighter profile. Built for fighter sponsor exposure.',free:true},
    {icon:'⭐',id:'five-sponsor-bar',name:'Five Sponsor Bar',price:'$500 / 28 days',desc:'Unlock up to five sponsor placements for 28 days. 3 month contract required.',free:false},
    {icon:'📣',id:'scrolling-advertiser-banner',name:'Scrolling Advertiser Banner',price:'$500 / ad / 28 days',desc:'Advertiser logo and landing URL appear in scrolling ad bars after admin approval.',free:false},
    {icon:'🎵',id:'ring-walk-music-affiliate',name:'Ring Walk Music Affiliate',price:'Coming soon',desc:'Fighter ring song will link through your music affiliate system when enabled.',coming:true},
    {icon:'🥊',id:'trainer-coach-plugin',name:'Trainer / Coach Plugin',price:'Coming soon',desc:'Adds trainer service tools to a profile without changing the fighter data sheet.',coming:true}
  ];
  const cards=catalogue.map(function(p){
    const a=active.find(x=>x.id===p.id && x.status==='active' && pf6daysLeft(x.expires)>0);
    let action='';
    if(p.free) action='<span style="color:var(--green);font-size:11px;font-weight:700">✓ Active</span>';
    else if(p.coming) action='<button class="btn-secondary" style="padding:8px 14px;font-size:11px;width:auto" disabled>Coming</button>';
    else if(a) action='<div style="text-align:right"><div>'+pf6contractStatus(a.expires)+'</div><button class="btn-secondary" style="padding:7px 10px;font-size:10px;margin-top:6px;width:auto" onclick="pf6cancelPlugin(\''+p.id+'\')">Cancel demo</button></div>';
    else action='<button class="btn-primary" style="padding:8px 14px;font-size:11px;width:auto" onclick="pf6purchasePlugin(\''+p.id+'\',\''+p.name.replace(/'/g,'')+'\',\''+p.price+'\')">Activate Demo</button>';
    return '<div class="plugin-card '+(p.free||a?'active-plugin':'')+'"><div class="plugin-header"><div class="plugin-icon-lg">'+p.icon+'</div><div style="flex:1"><div class="plugin-name">'+p.name+'</div><span class="plugin-tier '+(p.free?'tier-free':'tier-paid')+'">'+p.price+'</span></div>'+action+'</div><div class="plugin-desc">'+p.desc+'</div></div>';
  }).join('');
  const activePanel=active.length?'<div class="phase6-panel"><div class="phase6-title">Active / Demo Plugin Contracts</div>'+active.map(p=>'<div class="phase6-row"><div><b>'+pfEscape(p.name)+'</b><small>'+pfEscape(p.price)+' · '+pfEscape(p.contractTerm||'3 months')+'</small></div>'+pf6contractStatus(p.expires)+'</div>').join('')+'</div>':'';
  el.innerHTML='<div style="background:var(--black);border:2px solid var(--red);border-radius:2px;padding:14px;margin-bottom:16px;text-align:center"><div style="font-size:9px;letter-spacing:2px;text-transform:uppercase;color:var(--red);margin-bottom:6px">Phase 6 Commercial Plugin System</div><div style="font-size:12px;color:var(--gray-light);line-height:1.6">This is a frontend demo of how plugin purchases, 28-day access and 3-month contracts will look before PayPal/backend webhooks are connected.</div></div>'+activePanel+cards;
};

function pf6RenderSponsors(f){
  const pack=pf6activeSponsorPack();
  const base=(f&&f.sponsor&&f.sponsor.name)?[f.sponsor.name]:['Iron Supplements'];
  const sponsors=pack?base.concat(['Sponsor Slot 2','Sponsor Slot 3','Sponsor Slot 4','Sponsor Slot 5']).slice(0,5):base.slice(0,1);
  return '<div class="phase6-sponsor-strip"><div class="phase6-title">Official Sponsor'+(sponsors.length>1?'s':'')+'</div><div class="phase6-sponsor-grid">'+sponsors.map(s=>'<div class="phase6-sponsor"><div>⭐</div><span>'+pfEscape(s)+'</span></div>').join('')+'</div>'+(pack?'<div class="phase6-note">Five Sponsor Bar active: '+pf6daysLeft(pack.expires)+' days left.</div>':'<div class="phase6-note">Free profile allows 1 sponsor. Five sponsor plugin unlocks 5 slots.</div>')+'</div>';
}
const pf6OpenProfileBase=typeof openProfile==='function'?openProfile:null;
openProfile=function(id){
  if(pf6OpenProfileBase) pf6OpenProfileBase(id);
  setTimeout(function(){
    const f=fighters.find(x=>x.id===id); if(!f) return;
    const sections=[...document.querySelectorAll('.profile-section')];
    const firstSection=sections[0];
    if(firstSection && !document.querySelector('.phase6-sponsor-strip')) firstSection.insertAdjacentHTML('beforebegin', pf6RenderSponsors(f));
  },60);
};

