// ========== PHASE 9: PAYPAL-READY MONETIZATION FOUNDATION ==========
const PF_PHASE9_VERSION='phase9-paypal-monetization';
const PF9_PAYMENT_PRODUCTS = [
  {code:'plugin-online-trainer',type:'plugin',name:'Online Trainer Plugin',price:'$5/month',period:'Monthly',contract:'Monthly until cancelled',status:'PayPal plan required'},
  {code:'plugin-sponsor-link',type:'plugin',name:'Sponsor Link Plugin',price:'$9/month',period:'Monthly',contract:'Monthly until cancelled',status:'PayPal plan required'},
  {code:'plugin-five-sponsors',type:'plugin',name:'Five Sponsor Slots',price:'$500 / 28 days',period:'28 days',contract:'3 month contract',status:'PayPal subscription required'},
  {code:'ad-scroll-slot',type:'advertising',name:'Scrolling Advertising Banner',price:'$500 / 28 days',period:'28 days',contract:'3 month contract',status:'PayPal subscription required'},
  {code:'featured-merch',type:'merch',name:'Featured Merch Placement',price:'Admin controlled',period:'28 days',contract:'Optional',status:'Backend order required'}
];
function pf9GetContracts(){ try{return JSON.parse(localStorage.getItem('pf9_contracts')||'[]');}catch(e){return [];} }
function pf9SaveContracts(x){ localStorage.setItem('pf9_contracts',JSON.stringify(x||[])); }
function pf9DaysLeft(expires){ const d=Math.ceil((new Date(expires).getTime()-Date.now())/86400000); return d; }
function pf9ContractBadge(c){
  const d=pf9DaysLeft(c.expires_at);
  if(c.status==='expired' || d<=0) return '<span style="color:#ff4b4b;font-weight:900">Expired</span>';
  if(d<=7) return '<span style="color:#f5c518;font-weight:900">Renew soon · '+d+'d</span>';
  return '<span style="color:var(--green);font-weight:900">Active · '+d+'d</span>';
}
function pf9CreateDemoContract(code){
  const product=PF9_PAYMENT_PRODUCTS.find(p=>p.code===code); if(!product) return;
  const contracts=pf9GetContracts();
  contracts.unshift({
    id:'PF9-'+Date.now(), code:product.code, type:product.type, name:product.name, price:product.price,
    provider:'paypal', provider_subscription_id:'DEMO-SUB-'+Date.now(), status:'active', contract:product.contract,
    starts_at:new Date().toISOString(), expires_at:new Date(Date.now()+28*86400000).toISOString(), created_at:new Date().toISOString()
  });
  pf9SaveContracts(contracts);
  alert(product.name+' demo PayPal contract recorded. Live activation will require real PayPal webhook confirmation.');
  adminLoadPhase9Money();
}
function pf9ExpireContract(id){ const contracts=pf9GetContracts().map(c=>c.id===id?Object.assign({},c,{status:'expired',expires_at:new Date(Date.now()-86400000).toISOString()}):c); pf9SaveContracts(contracts); adminLoadPhase9Money(); }
function adminLoadPhase9Products(){
  const el=document.getElementById('admin-list'); if(!el) return;
  el.innerHTML='<div style="background:var(--black);border:1px solid var(--red);padding:12px;border-radius:2px;margin-bottom:12px">'
    +'<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--gray-text)">Phase 9 Monetization Rule</div>'
    +'<div style="font-size:16px;font-weight:900;color:#fff;margin:4px 0">PayPal activates only after verified webhook payment</div>'
    +'<div style="font-size:11px;color:var(--gray-light);line-height:1.6">Buttons in this demo record test contracts only. In production, PayPal subscription IDs must be verified by the backend webhook before plugins, ads or sponsor slots become active.</div></div>'
    +PF9_PAYMENT_PRODUCTS.map(function(p){return '<div style="background:var(--gray-dark);border:1px solid var(--gray-border);padding:12px;margin-bottom:8px;border-radius:2px">'
      +'<div style="display:flex;justify-content:space-between;gap:10px"><div><b style="color:#fff">'+pfEscape(p.name)+'</b><div style="font-size:11px;color:var(--gray-light);line-height:1.5">'+pfEscape(p.type)+' · '+pfEscape(p.period)+' · '+pfEscape(p.contract)+'</div></div><div style="text-align:right;color:var(--red);font-weight:900">'+pfEscape(p.price)+'</div></div>'
      +'<button class="btn-secondary" style="margin-top:10px;padding:8px;font-size:10px" onclick="pf9CreateDemoContract(\''+p.code+'\')">Record demo PayPal contract</button>'
      +'</div>';}).join('');
}
function adminLoadPhase9Money(){
  const el=document.getElementById('admin-list'); if(!el) return;
  const contracts=pf9GetContracts();
  const active=contracts.filter(c=>c.status==='active' && pf9DaysLeft(c.expires_at)>0).length;
  const renew=contracts.filter(c=>c.status==='active' && pf9DaysLeft(c.expires_at)>0 && pf9DaysLeft(c.expires_at)<=7).length;
  const expired=contracts.filter(c=>c.status==='expired' || pf9DaysLeft(c.expires_at)<=0).length;
  el.innerHTML='<div class="stats-bar" style="margin-bottom:12px"><div class="stat-item"><div class="stat-num">'+active+'</div><div class="stat-label">Active</div></div><div class="stat-item"><div class="stat-num">'+renew+'</div><div class="stat-label">Renew Soon</div></div><div class="stat-item"><div class="stat-num">'+expired+'</div><div class="stat-label">Expired</div></div></div>'
    +'<div style="font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--gray-text);margin-bottom:10px">Payment Contracts</div>'
    +(contracts.length?contracts.map(function(c){return '<div style="background:var(--gray-dark);border:1px solid var(--gray-border);padding:12px;margin-bottom:8px;border-radius:2px">'
      +'<div style="display:flex;justify-content:space-between;gap:10px"><div><b style="color:#fff">'+pfEscape(c.name)+'</b><div style="font-size:11px;color:var(--gray-light);line-height:1.5">'+pfEscape(c.price)+' · '+pfEscape(c.contract)+'<br>PayPal ID: '+pfEscape(c.provider_subscription_id)+'</div></div><div style="text-align:right">'+pf9ContractBadge(c)+'</div></div>'
      +'<button class="btn-secondary" style="margin-top:10px;padding:7px;font-size:10px" onclick="pf9ExpireContract(\''+c.id+'\')">Expire test</button>'
      +'</div>';}).join(''):'<div style="background:var(--gray-dark);border:1px solid var(--gray-border);padding:14px;color:var(--gray-light);font-size:12px">No payment contracts recorded yet. Open Products and record a demo PayPal contract.</div>');
}
