  const el=document.getElementById('admin-list'); if(!el) return;
  const steps=['Create PayPal subscription product/plan for each Prizefighter paid item','Frontend redirects buyer to PayPal checkout','PayPal sends event to POST /api/webhooks/paypal','Backend verifies PayPal signature and event ID','Backend records payment_events row for audit trail','Backend activates plugin/ad/sponsor contract for 28 days','Backend marks renew-soon inside last 7 days','Backend expires feature if renewal fails'];
