    +steps.map(function(s,i){return '<div style="background:var(--gray-dark);border:1px solid var(--gray-border);padding:11px;margin-bottom:7px;display:flex;gap:10px"><span style="color:var(--red);font-weight:900">'+(i+1)+'</span><span style="font-size:12px;color:var(--gray-light);line-height:1.5">'+pfEscape(s)+'</span></div>';}).join('');
