/* =========================
   PHASE 10 — PWA / MOBILE APP FOUNDATION
   ========================= */
const PF_PHASE10_VERSION = 'phase10-pwa-mobile-foundation';
window.PF_COMBAT_SPORTS_ONLY = ['Gloved Boxing', 'Bare Knuckle Boxing (BKB)'];

let pf10DeferredInstallPrompt = null;
function pf10EnsureInstallButton(){
  if(document.getElementById('pf-install-btn')) return;
  const btn=document.createElement('button');
  btn.id='pf-install-btn';
  btn.className='pf-install-btn';
  btn.textContent='Install App';
  btn.onclick=pf10InstallApp;
  document.body.appendChild(btn);
}
function pf10InstallApp(){
  if(!pf10DeferredInstallPrompt){ alert('Install from your browser menu: Add to Home Screen / Install app.'); return; }
  pf10DeferredInstallPrompt.prompt();
  pf10DeferredInstallPrompt.userChoice.finally(()=>{ pf10DeferredInstallPrompt=null; const b=document.getElementById('pf-install-btn'); if(b)b.style.display='none'; });
}
window.addEventListener('beforeinstallprompt', function(e){
  e.preventDefault();
  pf10DeferredInstallPrompt=e;
  pf10EnsureInstallButton();
  const b=document.getElementById('pf-install-btn'); if(b)b.style.display='block';
});
function pf10NetworkBadge(){
  let el=document.getElementById('pf-network-pill');
  if(!el){ el=document.createElement('div'); el.id='pf-network-pill'; el.className='pf-network-pill'; document.body.appendChild(el); }
  el.textContent = navigator.onLine ? 'Online' : 'Offline demo mode';
  el.style.display = navigator.onLine ? 'none' : 'block';
}
window.addEventListener('online',pf10NetworkBadge);
window.addEventListener('offline',pf10NetworkBadge);
setTimeout(pf10NetworkBadge,800);

function adminLoadPhase10PWA(){
  const el=document.getElementById('admin-list'); if(!el) return;
  const checks=[
    ['Manifest','manifest.json added for Android/iPhone home-screen install'],
    ['Service Worker','App shell cached for faster repeat loading'],
    ['Icons','192px, 512px and maskable icon placeholders included'],
    ['Offline Fallback','Static demo falls back to the main app when offline'],
    ['Mobile Rules','Portrait-first layout, app theme colour and viewport meta applied'],
    ['Native Ready','Can later wrap with Capacitor for Google Play / App Store builds']
  ];
  el.innerHTML='<div class="pf-pwa-card" style="border-color:var(--red)"><div class="pf-pwa-title">Phase 10 Mobile App Foundation</div><div class="pf-pwa-text">Prizefighter is now prepared as an installable PWA demo. This does not replace the production backend; it prepares the frontend for mobile users and future Android/iPhone packaging.</div></div>'+
    checks.map(function(c){return '<div class="pf-pwa-card"><div class="pf-pwa-title">'+pfEscape(c[0])+'</div><div class="pf-pwa-text">'+pfEscape(c[1])+'</div></div>';}).join('')+
    '<div class="pf-pwa-card"><div class="pf-pwa-title">Combat Sport Lock</div><div class="pf-pwa-text">Only Gloved Boxing and Bare Knuckle Boxing (BKB) are valid sports across signup, search, profile data and backend validation.</div></div>';
}
